import { app, BrowserWindow, Menu, ipcMain, dialog, IpcMainEvent, OpenDialogOptions, session, shell } from 'electron';
import path from 'path';
import os from 'os';
import { execSync } from 'child_process';
import { statSync } from 'fs';
import OpenClawService from './claw_service';
import OpenxBridge from './openx_bridge';
import { appLog } from './logger';
import { CorsHandler, CspHandler, FrameProtectionHandler, hasPermissionDevTools } from './web_disposer';
import { getDefaultWorkspacePath } from './utility';
import { AppConfig } from './app_config';
import { SplashWindow } from './splash_window';
import { configManager } from './config_manager';
import { Toast } from './toast';


process.on('unhandledRejection', (reason) => {
  appLog.error(`未处理的Promise拒绝: ${String(reason)}`);
});

process.on('uncaughtException', (err) => {
  appLog.error(`未捕获异常: ${err.message}\n${err.stack}`);
  Toast.show(err.message);
});

let canDebug = !app.isPackaged; // 开发环境直接允许，生产环境需验证权限文件
//let canDebug = false; // 默认生产环境，用于权限验证的代码测试
let verifyingPromise: Promise<void> | null = null; // 验证任务guard，防止重复启动
let mainWindow: BrowserWindow | null = null;

let ocService: OpenClawService = null!;
let openxBridge: OpenxBridge = null!;
let splashWindow: SplashWindow = null!;

const gotTheApplock = app.requestSingleInstanceLock();
if (!gotTheApplock) {
  appLog.info(`[启动] PID=${process.pid} 另一个实例已在运行，当前实例退出!`);
  app.quit();
} else {
  ocService = new OpenClawService(app);
  openxBridge = new OpenxBridge(() => mainWindow);
  splashWindow = new SplashWindow();

  appLog.info(`[启动] PID=${process.pid} yx-mate 应用启动, 等待 app.whenReady()...`);

  app.on('second-instance', () => {
    if (mainWindow) {
      if (mainWindow.isMinimized()) {
        mainWindow.restore();
      }
      mainWindow.show();
      mainWindow.focus();
    }
  });

  app.whenReady().then(async () => {
    try {
      appLog.info(`[启动] PID=${process.pid} app.whenReady() 已触发`);
      ocService.start();
      const bridgePromise = Promise.race([
        openxBridge.start(),
        new Promise<void>((_, reject) =>
          setTimeout(() => reject(new Error('OpenX bridge 启动超时 10s')), 10000)
        )
      ]);
      initSessionHandle();
      createWindow();
      HandleMainWindowEvent();

      splashWindow.create();
      ocService.waitForService(() => {
        if (mainWindow) {
          mainWindow.webContents.once('did-finish-load', () => {
            splashWindow.close();
            mainWindow?.maximize();
            mainWindow?.show();
          });
          //mainWindow.loadURL(ocService.targetUrl);
          mainWindow.loadURL(configManager.getMainUrl());
        }
      });
      await bridgePromise;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      appLog.error(`[启动] PID=${process.pid} 启动失败: ${msg}`);
      dialog.showErrorBox('启动失败', `应用启动失败: ${msg}`);
      app.quit();
    }
  });
}

function createWindow(): void {
  mainWindow = new BrowserWindow({
    width: 1200,
    height: 800,
    title: '小研Mate',
    show: false,
    autoHideMenuBar: true,
    titleBarOverlay: {
      color: '#f0f0f9',
      symbolColor: '#333333',
    },
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      preload: path.join(__dirname, 'preload.js'),
      //webSecurity: false, // 禁用安全检查
      devTools: true,
    }
  });

  if (process.platform === 'darwin') {
    mainWindow.setAutoHideMenuBar(true);
  } else {
    Menu.setApplicationMenu(null);
  }

  // if (canDebug) {
  //   mainWindow.webContents.openDevTools({ mode: 'detach' });
  // }

  mainWindow.webContents.on('console-message', (_event, level, message, line, sourceId) => {
    appLog.writeFromRenderer(message, level, sourceId, line);
  });

  mainWindow.on('closed', () => {
    mainWindow = null;
  });
}

function initSessionHandle(): void {
  // ===== 请求端 =====
  session.defaultSession.webRequest.onBeforeSendHeaders(
    { urls: ['*://*/*'] },
    (details, callback) => {
      const modifiedHeaders = CorsHandler.onBeforeSendHeaders(
        details.requestHeaders,
        details.id,
        details.url,
      );
      callback({ requestHeaders: modifiedHeaders });
    }
  );

  // ===== 响应端 =====
  session.defaultSession.webRequest.onHeadersReceived(
    { urls: ['*://*/*'] },
    (details, callback) => {
      let currentHeaders = { ...details.responseHeaders };

      currentHeaders = CorsHandler.onHeadersReceived(currentHeaders, details.id, details.url);
      currentHeaders = CspHandler.onHeadersReceived(currentHeaders, details.url);
      currentHeaders = FrameProtectionHandler.onHeadersReceived(currentHeaders, details.url);

      callback({ responseHeaders: currentHeaders });
    }
  );

  // ===== 缓存清理 =====
  session.defaultSession.webRequest.onErrorOccurred(
    { urls: ['*://*/*'] },
    (details) => {
      CorsHandler.onErrorOccurred(details.id);
    }
  );
}

function HandleMainWindowEvent(): void {
  HandleMainWindowKeydown();
  HandleMainWindowErrorPage();
  HandleMainWndowOpenUrl();
}

function HandleMainWindowErrorPage(): void {
  if (!mainWindow) return;

  mainWindow.webContents.on('did-fail-load', (event, errorCode, errorDescription, validatedURL, isMainFrame) => {
  if (!isMainFrame) {
    // 这是一个 iframe 加载失败
    // 我们可以通过执行 JS，在对应的 iframe 注入错误信息
    const injectJs = `
      var iframes = document.getElementsByTagName('iframe');
      for (var i = 0; i < iframes.length; i++) {
        if (iframes[i].src === "${validatedURL}") {
          iframes[i].srcdoc = "<html><body><h4 style='color:red;'>HTTP Error: ${errorCode}</h4><p style='color:red;'>${errorDescription}</p></body></html>";
        }
      }
    `;

    if (!mainWindow) return;
    mainWindow.webContents.executeJavaScript(injectJs);
  }
});
}

function openOrFocusDevTools(): void {
  if (!mainWindow) return;
  if (mainWindow.webContents.isDevToolsOpened()) {
    mainWindow.webContents.devToolsWebContents?.focus();
  } else {
    mainWindow.webContents.openDevTools({
      mode: 'undocked',
      activate: true,
    });
  }
}

function HandleMainWindowKeydown(): void {
  if (!mainWindow) return;

  mainWindow.webContents.on('before-input-event', (event, input) => {
    if (input.type !== 'keyDown') return;

    // 1. 匹配 F12
    const isF12 = input.key === 'F12';

    // 2. 匹配 Ctrl + Shift + I (Windows / Linux)
    const isWinCtrlShiftI = input.control && input.shift && input.key.toLowerCase() === 'i';

    // 3. 匹配 Cmd + Option + I (macOS)
    // 在 Electron 中，Mac 的 Command 键对应 input.meta，Option 对应 input.alt
    const isMacCmdOptionI = input.meta && input.alt && input.key.toLowerCase() === 'i';

    if (isF12 || isWinCtrlShiftI || isMacCmdOptionI) {
      event.preventDefault();

      if (canDebug) {
        openOrFocusDevTools();
        return;
      }

      if (!verifyingPromise) {
        verifyingPromise = (async () => {
          appLog.info('[DevTools] 开始权限验证...');
          try {
            const result = await hasPermissionDevTools();
            if (result) {
              canDebug = true;
              appLog.info('[DevTools] 权限验证通过');
              openOrFocusDevTools();
            } else {
              appLog.warn('[DevTools] 权限验证失败');
              // 失败后冷却 1 秒，防止按键重复事件快速触发多轮验证
              await new Promise(r => setTimeout(r, 1000));
            }
          } catch (err) {
            appLog.error(`[DevTools] 权限验证异常: ${err}`);
          } finally {
            verifyingPromise = null;
          }
        })();
      }
    }
  });
}

function HandleMainWndowOpenUrl(): void {
  if (!mainWindow) return;

  const isLocalUrl = (url: string) =>
    url.startsWith('http://127.0.0.1') || url.startsWith('http://localhost') || url.startsWith('file://');

  const isCnkiDomain = (url: string): boolean => {
    try {
      const hostname = new URL(url).hostname;
      return hostname === 'cnki.net' || hostname.endsWith('.cnki.net');
    } catch {
      return false;
    }
  };

  const appendLidParam = async (url: string): Promise<string> => {
    try {
      const cookies = await session.defaultSession.cookies.get({ name: 'LID' });
      const lidCookie = cookies.find(c => c.name === 'LID' && c.value);
      if (lidCookie) {
        const new_url = configManager.buildReadUrl(lidCookie.value, url);
        return new_url;
        // const separator = url.includes('?') ? '&' : '?';
        // const url_appended_lid = `${url}${separator}LID=${encodeURIComponent(lidCookie.value)}`;
        // return url_appended_lid;
      }
    } catch {
      // 获取 cookie 失败，返回原始 url
    }
    return url;
  };

  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    // 1. 允许本地 URL 在应用内打开
    if (isLocalUrl(url)) {
      return { action: 'allow' };
    }

    // 对于非本地 URL，默认使用外部浏览器打开
    if (url.startsWith('http://') || url.startsWith('https://')) {
      if (isCnkiDomain(url)) {
        appendLidParam(url).then(finalUrl => shell.openExternal(finalUrl));
      } else {
        shell.openExternal(url);
      }
      return { action: 'deny' };
    }

    // 其他协议（如 mailto:）使用默认处理
    return { action: 'allow' };
  });

  mainWindow.webContents.on('will-navigate', (event, url) => {
    let sameOrigin = false;
    try {
      const currentOrigin = new URL(mainWindow!.webContents.getURL()).origin;
      const targetOrigin = new URL(url).origin;
      sameOrigin = currentOrigin === targetOrigin;
    } catch {
      // URL 解析失败，视为非同源
    }

    if (!sameOrigin) {
      event.preventDefault();
    }
  });
}

async function packLogsToZip(sourceDir: string, destPath: string): Promise<void> {
  if (process.platform === 'win32') {
    const escapedSource = sourceDir.replace(/'/g, "''");
    const escapedDest = destPath.replace(/'/g, "''");
    execSync(`powershell -NoProfile -Command "Compress-Archive -Path '${escapedSource}\\*' -DestinationPath '${escapedDest}'"`, {
      encoding: 'utf-8',
      windowsHide: true,
    });
  } else {
    execSync(`cd "${sourceDir}" && zip -r "${destPath}" .`, { encoding: 'utf-8' });
  }
}

