ipcMain.handle('export-logs', async (): Promise<string | null> => {
  const browserWindow = BrowserWindow.getFocusedWindow() || mainWindow;
  if (!browserWindow) return null;

  const now = new Date();
  const ts = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}_${String(now.getHours()).padStart(2, '0')}-${String(now.getMinutes()).padStart(2, '0')}-${String(now.getSeconds()).padStart(2, '0')}`;
  const defaultName = `xy-mate_logs_${ts}.zip`;

  const result = await dialog.showSaveDialog(browserWindow, {
    title: '导出日志',
    defaultPath: defaultName,
    filters: [{ name: 'ZIP 压缩文件', extensions: ['zip'] }],
  });

  if (result.canceled || !result.filePath) return null;

  const logDir = path.join(app.getPath('userData'), 'logs');
  const destPath = result.filePath;

  try {
    await packLogsToZip(logDir, destPath);
    appLog.info(`导出日志成功: ${destPath}`);
    return destPath;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    appLog.error(`导出日志失败: ${msg}`);
    throw new Error(`导出日志失败: ${msg}`);
  }
});

